      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "Diffusion-based molecular graph generative models have achieved significant success in template-free, single-step retrosynthesis prediction.",
      "id": "evidence:topic:40155e879d76a19175f888c241373af25f03a31dcb7892417f48ceba6757ab3f",
