      "source_url": "https://openalex.org/W4409363354",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "Community detection is a research hotspot in machine learning and data mining.",
      "id": "evidence:topic:65e8da8202655074fb4fa3623ec20bf9b994dc063163ebb4a1dde44a66ed140c",
      "kind": "inferred_topic",
      "raw_sha256": "eeb9bcab4bb883404e53b730a2014d1494265482cd786965c56aba925d2c7351",
