      "source_locator": "openalex-request:14f87b1d701f67df72908ac9dc4bc6201f1cff352b9327b0aad11398dd3f534e#results[28];abstract[321:602]",
      "source_url": "https://openalex.org/W4414359918",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "To handle this issue, advanced methods are proposed to distill the affinity knowledge between images and texts from the old model to the new one for anti-forgetting.",
      "id": "evidence:topic:6410747ebb873fd6ff2d00ac25de532ae033b7a3ebda4a88118493c6a82ac1a0",
