      "source_url": "https://openalex.org/W4393159604",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "In this paper, we propose SheetPT, the first pre-training technique on spreadsheets to enable effective representation learning under this scenario.",
      "id": "evidence:topic:6489b53d6813fb47694586ddb4acaa27d44e7acaac0d5e1586558f85eb607b17",
      "kind": "inferred_topic",
      "raw_sha256": "2f0fca5dc29f7174650aa5d96388b2d4307b0a6f130733414e10debfdff1a302",
