      "source_locator": "openalex-request:a0ffca83d6193c00c1dded26a073da0fa10c777c4afb89663ddd44edd49e12ae#results[8];abstract[869:1029]",
      "source_url": "https://openalex.org/W4285605794",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "With no assumptions about the new training data, we estimate the sub-cluster structures of old embeddings.",
