      "source_url": "https://openalex.org/W4385768116",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "Specifically, we introduce four self-supervised tasks including next session prediction, utterance restoration, incoherence detection and consistency discrimination, and jointly train the PLM-based response selection model with these auxiliary tasks in a multi-task manner.",
      "id": "evidence:topic:9b8c472bdbc80c45482f6fe76963316f6ceaebd6e9bac546aade23a8e1fdaace",
      "kind": "inferred_topic",
