      "source_url": "https://openalex.org/W4285601398",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "We evaluate our proposed method, FlexPose, on several cross-dataset settings both qualitatively and quantitatively, which demonstrates that our approach achieves state-of-the-art performance compared to the existing generative-model-based transfer learning methods when given limited annotation guidance.",
      "id": "evidence:topic:a4754dafec82f7cca98d167b455d1c88023fc86e38c580dd145af8233bf03b04",
      "kind": "inferred_topic",
      "raw_sha256": "9dbb03b8bd7c1353c9d23772f578f5ff15c842ad717500714de525b854097212",
      "retrieved_at": "2026-11-07T20:29:42.145485Z",
