      "source_url": "https://openalex.org/W4401024866",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "Existing semi-supervised learning algorithms adopt pseudo-labeling and consistency regulation techniques to introduce supervision signals for unlabeled samples.",
      "id": "evidence:topic:afd789d216c616df44d9f373979787813f906b913645510b5b7c1173b9f5ef19",
      "kind": "inferred_topic",
      "raw_sha256": "06387e3e96588fb80a294cb684625ab287e0b30ab3a077bb4979a23456c3a4be",
      "retrieved_at": "2026-11-07T20:30:50.041586Z",
