      "source_url": "https://openalex.org/W3199148273",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "Furthermore, we apply various receptive fields in different feature groups to enhance representation learning.",
      "id": "evidence:topic:c19dd5eaa485c60d708019eaeff5697b0cd3d86716b7b4528fd1d2c76c3f9b36",
      "kind": "inferred_topic",
