      "source_locator": "openalex-request:07c51861e3646b310ee2ce71a131691b4634eb136e6ea69a58999e9def926f46#results[13];abstract[758:888]",
      "source_url": "https://openalex.org/W4409366418",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "In this paper, we present the Multi-Grained Target Perception network (MTPNet) to incorporate the prior knowledge of interactions between the molecules and their target proteins.",
      "id": "evidence:topic:cc5a2a8a006b1461ddd52a6e8b947704de3b640cc626526a8fdb73dbfef9bbf3",
      "kind": "inferred_topic",
