      "kind": "inferred_topic",
      "raw_sha256": "fbccb6e9eb4aa2c980682e23ddab20e5ffcec71aeb2d748adea413e025dd8750",
      "retrieved_at": "2026-11-07T20:31:16.843757Z",
      "source_locator": "openalex-request:d8f2ed8af477efc6f15356cb58e88b0b7280383958fea81aa8896689a7e974b2#results[48];abstract[348:469]",
